from scipy.integrate import quad

def fX(x):
    """
    Compute the marginal density  f_X(x) = ∫ f_XY(x,y) dy.
    """
    def fXY_at_x(y):
        return rvXY.pdf([x,y])
    return quad(fXY_at_x, a=-np.inf, b=np.inf)[0]

